#!/usr/bin/env python3
"""Single-request JSON entry point for the CrossCheck replay validator."""
import json
import math
import sys

from crosscheck import CrossCheck


def _pairs(items):
    result = {}
    for key, value in items:
        if key in result:
            raise ValueError("duplicate object key")
        result[key] = value
    return result


def _finite_float(text):
    value = float(text)
    if not math.isfinite(value):
        raise ValueError("nonfinite number")
    return value


def _reject_constant(text):
    raise ValueError("nonfinite constant")


def _load_request(data):
    # A UTF-8 BOM is not accepted as a JSON whitespace character.
    if data.startswith(b"\xef\xbb\xbf"):
        raise ValueError("UTF-8 BOM")
    text = data.decode("utf-8")
    return json.loads(
        text,
        object_pairs_hook=_pairs,
        parse_float=_finite_float,
        parse_constant=_reject_constant,
    )


def main():
    try:
        request = _load_request(sys.stdin.buffer.read())
        streams = request["streams"]
        output_streams = []
        for stream in streams:
            engine = CrossCheck(stream["topology"])
            event_answers = engine.replay(stream["events"], stream["settings"])
            output_streams.append({"events": event_answers})
        result = {"streams": output_streams}
        sys.stdout.write(json.dumps(result, separators=(",", ":"),
                                    ensure_ascii=True, allow_nan=False))
        sys.stdout.write("\n")
    except Exception:
        # Invalid JSON (including duplicate keys, invalid UTF-8, BOMs, empty
        # input, and nonfinite constants) has exactly one wire response.
        sys.stdout.write('{"error":"invalid_json"}\n')


if __name__ == "__main__":
    main()
